#!/usr/bin/env python
# ── GENERATED by matsci-knowledge-base build/build_plugin.py — DO NOT EDIT (真源见 plugin.yaml) ──
# -*- coding: utf-8 -*-
"""找出依赖「AI 分析报告」作为证据的 source 页。

背景：raw/ 中混有 lit-read 管线生成的 AI 分析报告（frontmatter 含
      type: literature-note / mode: 精读 / 标题带「AI 文献分析报告」）。
      若某 source 页以此类文件为唯一证据，其证据等级低于普通二手转述。

用法:
    python tools/qc_find_ai_deps.py              # 干跑
    python tools/qc_find_ai_deps.py --selftest   # 校验器自检
"""
import sys, os, re, glob, json, argparse


ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
os.chdir(ROOT)
sys.path.insert(0, "tools")
from kb_lib import read_text, qc_work_dir  # noqa: E402
from kb_lib import console_encoding
console_encoding()

AI = re.compile(r"type:\s*literature-note|AI 文献分析报告|AI文献分析报告"
                r"|mode:\s*[\"']?(精读|速读|深度)")


def norm(p):
    return p.replace(os.sep, "/").replace("\\", "/")


def scan():
    """返回 (ai_reports, out) 两份清单。"""
    ai_reports = []
    for f in sorted(glob.glob("raw/**/*.md", recursive=True)):
        try:
            t = read_text(f)
        except Exception:
            continue
        if AI.search(t[:3000]):
            ai_reports.append(norm(f))
    ai_set = set(ai_reports)

    out = []
    for f in sorted(glob.glob("wiki/sources/*.md")):
        t = read_text(f)
        head = t[: t.find("\n---", 3) + 4]
        raws = [norm(r) for r in re.findall(r"\[\[(raw/[^\]|]+)", head)]
        bad = [r for r in raws if r in ai_set]
        if not bad:
            continue
        others = [r for r in raws if r not in ai_set]
        out.append({"page": os.path.basename(f)[:-3], "ai": bad, "others": others})
    return ai_reports, out


def selftest():
    """校验器自检：已知答案反算（正例 + 反例）。"""
    ok = True
    # 正例：三种 AI 报告标记都必须命中
    for s, want in (("type: literature-note", True),
                    ("# AI 文献分析报告", True),
                    ('mode: "精读"', True)):
        got = bool(AI.search(s))
        print(f"  [{'ok' if got == want else 'FAIL'}] 标记正例命中: {s[:22]!r} -> {got}")
        ok = ok and got == want
    # 反例：普通论文 frontmatter 不得命中（否则会把一手原文误判为 AI 报告）
    plain = ('---\ntype: source\ntitle: "A study"\nauthors: ["A B"]\n'
             'source_reliability: "同行评审（Nature）"\n---\n正文')
    got = bool(AI.search(plain))
    print(f"  [{'ok' if not got else 'FAIL'}] 反例 普通论文 frontmatter 不命中")
    ok = ok and not got
    # 正例：真实库扫描跑通
    ai_reports, out = scan()
    print(f"  [{'ok' if True else 'FAIL'}] 全库扫描 -> AI 报告 {len(ai_reports)} 份，"
          f"受影响 source 页 {len(out)} 页")
    # 正例：写盘目标在库根、未落归档
    wd = qc_work_dir(create=True)
    safe = "_archive" not in wd.replace("/", "\\")
    print(f"  [{'ok' if safe else 'FAIL'}] 写盘目标在库根、未落归档 -> {wd}")
    ok = ok and safe
    print("=== selftest", "PASS ===" if ok else "FAIL ===")
    return 0 if ok else 1


def main():
    ap = argparse.ArgumentParser(description="查找依赖 AI 分析报告的 source 页")
    ap.add_argument("--selftest", action="store_true", help="校验器自检")
    a = ap.parse_args()
    if a.selftest:
        return selftest()

    ai_reports, out = scan()
    print("raw/ 中的 AI 分析报告: %d 份" % len(ai_reports))
    for x in ai_reports:
        print("   %7d B  %s" % (os.path.getsize(x), x))

    print("\n受影响 source 页:")
    for r in out:
        print("\n  🔴 %s" % r["page"])
        for b in r["ai"]:
            print("       AI报告: %s (%d B)" % (b, os.path.getsize(b)))
        if r["others"]:
            print("       其他来源: %s" % r["others"])
        else:
            print("       ⚠️ 唯一证据就是 AI 报告")

    o = os.path.join(qc_work_dir(create=True), "ai_deps.json")
    json.dump(out, open(o, "w", encoding="utf-8"),
              ensure_ascii=False, indent=1)
    print("\n共 %d 页受影响，清单 -> %s" % (len(out), o))
    return 0


if __name__ == "__main__":
    sys.exit(main())
